<?php
require_once __DIR__.'/includes/auth.php';require_login();require_once __DIR__.'/includes/helpers.php';$pageTitle='Inscripción y roster';
$role=current_role();
try{$torneos=option_map('torneos');$teams=option_map('equipos');if($role==='CAPITAN'){$teams=[];foreach(lookup_rows('equipos') as $r){if((string)$r['ID_CAPITAN']===(string)current_user()['ID_USUARIO'] && $r['ESTADO']==='ACTIVO')$teams[$r['ID_EQUIPO']]=$r['NOMBRE'];}}
$selected=$_GET['torneo']??($_POST['torneo']??array_key_first($torneos));$ins=$selected?oracle_cursor('AV_JP_RM_BE_SP_INSCRIPCION_LISTAR',['P_ID_TORNEO'=>$selected]):[];
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['inscribir'])){$sql='BEGIN AV_JP_RM_BE_SP_INSCRIBIR_EQUIPO(:P_ID_TORNEO,:P_ID_EQUIPO,:P_MONTO_PAGADO,:P_ID_INSCRIPCION); END;';$p=['P_ID_TORNEO'=>$_POST['torneo'],'P_ID_EQUIPO'=>$_POST['equipo'],'P_MONTO_PAGADO'=>$_POST['monto'],'P_ID_INSCRIPCION'=>0];$out=oracle_run($sql,$p,['P_ID_INSCRIPCION']);flash('success','Equipo inscrito. ID inscripción '.$out['P_ID_INSCRIPCION'].'; el roster se cargó automáticamente.');header('Location: gestor_inscripciones.php?torneo='.urlencode($_POST['torneo']));exit;}}
catch(Throwable $e){$error=$e->getMessage();}
include __DIR__.'/includes/header.php';function opti($a,$sel=null){foreach($a as $v=>$l)echo '<option value="'.h($v).'" '.((string)$v===(string)$sel?'selected':'').'>'.h($l).'</option>';}?>
<main class="content"><div class="page-head"><div><h1>📝 Inscripción de equipos y roster</h1><p>Gestor 2: valida cupos, crea la inscripción y recorre los jugadores activos del equipo mediante cursor.</p></div></div><?php if(!empty($error)):?><div class="callout" style="border-color:#ff667d"><?=h($error)?></div><?php endif;?><div class="grid grid-2"><section class="panel"><h2 class="section-title">Inscribir equipo</h2><form method="post"><input type="hidden" name="inscribir" value="1"><div class="field"><label>Torneo *</label><select name="torneo" required><?php opti($torneos??[],$selected??null)?></select></div><div class="field"><label>Equipo *</label><select name="equipo" required><?php opti($teams??[])?></select></div><div class="field"><label>Monto pagado *</label><input type="number" min="0" name="monto" value="0" required></div><div class="form-actions"><button class="btn">Inscribir y generar roster</button></div></form><?php if($role==='CAPITAN'):?><div class="callout" style="margin-top:16px">Como capitán, solo puedes inscribir equipos asociados a tu usuario.</div><?php endif;?></section><section class="panel"><h2 class="section-title">Consultar inscritos</h2><form method="get"><div class="field"><label>Torneo</label><select name="torneo" onchange="this.form.submit()"><?php opti($torneos??[],$selected??null)?></select></div></form><div class="table-wrap"><table><thead><tr><th>ID</th><th>Equipo</th><th>Fecha</th><th>Pagado</th><th>Puntos</th><th>Estado</th></tr></thead><tbody><?php foreach($ins??[] as $r):?><tr><td><?=h($r['ID_INSCRIPCION'])?></td><td><?=h($r['EQUIPO'])?></td><td><?=h($r['FECHA_INSCRIPCION'])?></td><td><?=money($r['MONTO_PAGADO'])?></td><td><?=h($r['PUNTOS'])?></td><td><span class="badge <?=h($r['ESTADO'])?>"><?=h($r['ESTADO'])?></span></td></tr><?php endforeach;?></tbody></table></div></section></div></main><?php include __DIR__.'/includes/footer.php';?>
